@Composable
fun ChatsScreen(
    viewModel: ChatsViewModel,
    onNodeClick: (MeshNode) -> Unit,
    modifier: Modifier = Modifier
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    Column(
        modifier = modifier.fillMaxSize()
    ) {
        // Optional Search Bar inside content body
        OutlinedTextField(
            value = uiState.searchQuery,
            onValueChange = { viewModel.onSearchQueryChanged(it) },
            placeholder = { Text("Search conversations...", color = MeshTextSecondary) },
            singleLine = true,
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = MeshSpacing.md, vertical = MeshSpacing.xs)
        )

        if (uiState.conversations.isEmpty()) {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = "No active conversations",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MeshTextSecondary
                )
            }
        } else {
            LazyColumn(
                modifier = Modifier.fillMaxSize()
            ) {
                items(
                    items = uiState.conversations,
                    key = { it.node.id }
                ) { conversation ->
                    ChatItemRow(
                        conversation = conversation,
                        onClick = { onNodeClick(conversation.node) }
                    )
                    HorizontalDivider(color = MeshBorder)
                }
            }
        }
    }
}



