@Composable
fun HomeScreen(
    viewModel: HomeViewModel,
    onNavigateToNearbyNodes: () -> Unit,
    onNavigateToNetworkInterfaces: () -> Unit,
    onNavigateToProfile: () -> Unit,
    onNavigateToAbout: () -> Unit,
    onNavigateToLogs: () -> Unit,
    modifier: Modifier = Modifier
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val scrollState = rememberScrollState()

    Column(
        modifier = modifier
            .fillMaxSize()
            .verticalScroll(scrollState)
            .padding(MeshSpacing.md),
        verticalArrangement = Arrangement.spacedBy(MeshSpacing.md)
    ) {
        // Network Status Overview
        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = MeshBg1)
        ) {
            Column(modifier = Modifier.padding(MeshSpacing.md)) {
                Text(
                    text = "Node Status",
                    style = MaterialTheme.typography.titleSmall,
                    color = MeshTextSecondary
                )
                Spacer(modifier = Modifier.height(MeshSpacing.xs))
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(MeshSpacing.xs)
                ) {
                    Text(
                        text = if (uiState.isNodeActive) "Active & Mesh-Connected" else "Offline",
                        style = MaterialTheme.typography.titleMedium,
                        fontWeight = FontWeight.Bold,
                        color = if (uiState.isNodeActive) MeshGreen else MaterialTheme.colorScheme.error
                    )
                }
                Spacer(modifier = Modifier.height(MeshSpacing.xs))
                Text(
                    text = "Connected Peers: ${uiState.connectedPeersCount}",
                    style = MaterialTheme.typography.bodyMedium,
                    color = MeshTextPrimary
                )
            }
        }

        // Action Menu Options
        Text(
            text = "Quick Actions",
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold,
            color = MeshTextPrimary,
            modifier = Modifier.padding(top = MeshSpacing.xs)
        )

        Button(
            onClick = onNavigateToNearbyNodes,
            modifier = Modifier.fillMaxWidth()
        ) {
            Icon(imageVector = Icons.Outlined.Share, contentDescription = null)
            Spacer(modifier = Modifier.padding(start = MeshSpacing.xs))
            Text("Discover Nearby Nodes")
        }

        OutlinedButton(
            onClick = onNavigateToNetworkInterfaces,
            modifier = Modifier.fillMaxWidth()
        ) {
            Icon(imageVector = Icons.Outlined.Router, contentDescription = null)
            Spacer(modifier = Modifier.padding(start = MeshSpacing.xs))
            Text("Network Interfaces")
        }

        OutlinedButton(
            onClick = onNavigateToProfile,
            modifier = Modifier.fillMaxWidth()
        ) {
            Icon(imageVector = Icons.Outlined.Person, contentDescription = null)
            Spacer(modifier = Modifier.padding(start = MeshSpacing.xs))
            Text("My Node Profile")
